```ts
import { generateText } from 'ai';

const result = await generateText({
  model: '...',
  // your configuration
});

const fullMessageHistory = result.steps.flatMap(step => [
  ...(step.experimental_steeringMessages ?? []),
  ...step.response.messages,
]);

// Save fullMessageHistory to your database
```

